def link(self, text, as_html=True) -> str:
        """
        Generate URL for using in text messages with HTML or MD parse mode

        :param text: link label
        :param as_html: generate as HTML
        :return: str
        """
        if not self.url:
            raise ValueError("Link URL is not set")
        if not text:
            raise ValueError("Link text is not set")

        if as_html:
            return f'<a href="{self.url}">{text}</a>'
        else:
            return f'[{text}]({self.url})'

